-- Product bill of materials and ordered manufacturing routing.
create table public.product_bom_items(bom_item_id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(product_id)on delete cascade,material_id uuid not null references public.materials(material_id),quantity_per_unit numeric not null check(quantity_per_unit>0),uom_id uuid not null references public.uoms(uom_id),wastage_percent numeric not null default 0 check(wastage_percent>=0),notes text,active_status boolean not null default true,created_at timestamptz not null default now(),created_by text not null default'system',updated_at timestamptz not null default now(),updated_by text,unique(product_id,material_id));
create table public.product_routing_steps(routing_step_id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(product_id)on delete cascade,step_no int not null check(step_no>0),step_name text not null,machine_group_id uuid not null references public.machine_groups(machine_group_id),standard_minutes numeric check(standard_minutes is null or standard_minutes>0),instructions text,active_status boolean not null default true,created_at timestamptz not null default now(),created_by text not null default'system',updated_at timestamptz not null default now(),updated_by text,unique(product_id,step_no));
create or replace function public.add_product_bom_item(p_product uuid,p_material uuid,p_quantity numeric,p_uom uuid,p_wastage numeric default 0,p_notes text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not has_factory_role(auth.uid(),array['admin','production_manager'])then raise exception'not authorized';end if;insert into product_bom_items(product_id,material_id,quantity_per_unit,uom_id,wastage_percent,notes,created_by)values(p_product,p_material,p_quantity,p_uom,coalesce(p_wastage,0),p_notes,auth.uid()::text)returning bom_item_id into v_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'BOM Component Added','product_bom_items',v_id,jsonb_build_object('product_id',p_product,'material_id',p_material,'quantity',p_quantity));return v_id;end$$;
create or replace function public.add_product_routing_step(p_product uuid,p_step int,p_name text,p_group uuid,p_minutes numeric default null,p_instructions text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not has_factory_role(auth.uid(),array['admin','production_manager'])then raise exception'not authorized';end if;insert into product_routing_steps(product_id,step_no,step_name,machine_group_id,standard_minutes,instructions,created_by)values(p_product,p_step,p_name,p_group,p_minutes,p_instructions,auth.uid()::text)returning routing_step_id into v_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Routing Step Added','product_routing_steps',v_id,jsonb_build_object('product_id',p_product,'step_no',p_step,'machine_group_id',p_group));return v_id;end$$;
alter table public.product_bom_items enable row level security;alter table public.product_routing_steps enable row level security;
create policy factory_read_bom on public.product_bom_items for select using(has_factory_role(auth.uid()));create policy factory_read_routing on public.product_routing_steps for select using(has_factory_role(auth.uid()));
grant execute on function public.add_product_bom_item(uuid,uuid,numeric,uuid,numeric,text)to authenticated;grant execute on function public.add_product_routing_step(uuid,int,text,uuid,numeric,text)to authenticated;
